const $=(s)=>document.querySelector(s);
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const header=$('.header');
if(header){let queued=false;const updateHeader=()=>{const compact=header.classList.contains('is-scrolled');header.classList.toggle('is-scrolled',window.scrollY>(compact?20:80));queued=false};window.addEventListener('scroll',()=>{if(!queued){queued=true;requestAnimationFrame(updateHeader)}},{passive:true});window.addEventListener('pageshow',updateHeader);updateHeader()}
const dialog=$('#estimate-dialog');
const form=$('#estimate-form');
function openEstimate(service){if(service)form.elements.service.value=service;$('#estimate-result').hidden=true;dialog.showModal();document.body.classList.add('modal-open')}
document.querySelectorAll('[data-estimate]').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();openEstimate()}));
document.querySelectorAll('[data-service]').forEach(b=>b.addEventListener('click',()=>openEstimate(b.dataset.service)));
dialog.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());
dialog.addEventListener('close',()=>document.body.classList.remove('modal-open'));
dialog.addEventListener('click',e=>{if(e.target===dialog){const b=dialog.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)dialog.close()}});
$('.menu-button').addEventListener('click',()=>{const open=$('#nav').classList.toggle('open');$('.menu-button').setAttribute('aria-expanded',open);$('.menu-button').setAttribute('aria-label',open?'Close navigation':'Open navigation')});
document.querySelectorAll('#nav a').forEach(a=>a.addEventListener('click',()=>{$('#nav').classList.remove('open');$('.menu-button').setAttribute('aria-expanded','false')}));
form.addEventListener('submit',e=>{e.preventDefault();const d=new FormData(form);const message=`Hi Smart Way! I'd like a free repair estimate.\nName: ${d.get('name').trim()}\nCity: ${d.get('city').trim()}\nVehicle: ${d.get('vehicle').trim()}\nService: ${d.get('service')}\nPreference: ${d.get('location')}\nDamage: ${d.get('damage').trim()}\nI'll attach photos of the damage.`;$('#prepared-message').value=message;const separator=/iPad|iPhone|iPod/.test(navigator.userAgent)?'&':'?';$('#sms-link').href=`sms:+19549052386${separator}body=${encodeURIComponent(message)}`;$('#estimate-result').hidden=false;$('#copy-status').textContent='';$('#estimate-result').scrollIntoView({behavior:reduced?'auto':'smooth',block:'nearest'})});
$('.copy-button').addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('#prepared-message').value);$('#copy-status').textContent='Copied. Paste it into a text to (954) 905-2386.'}catch{$('#prepared-message').focus();$('#prepared-message').select();$('#copy-status').textContent='Select and copy the message above.'}});
document.querySelectorAll('[data-mode]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-mode]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});const shop=b.dataset.mode==='shop';$('#step-title').textContent=shop?'Come by. We’ll take a look.':'Pick your place.';$('#step-copy').textContent=shop?'Visit our Oakland Park shop for a closer look, including collision and larger repairs. Ask about free pick-up and delivery.':'Your driveway, your office, your schedule. We’ll confirm if mobile service is right for your repair.';if(window.gsap&&!reduced)gsap.fromTo('#step-title, #step-copy',{opacity:0,y:7},{opacity:1,y:0,duration:.3,stagger:.04})}));
const counties={'Broward':['Fort Lauderdale','Oakland Park','Hollywood','Pompano Beach','Coral Springs','Deerfield Beach','Davie','Plantation','Pembroke Pines','Weston','Coconut Creek','Wilton Manors','Sunrise','Miramar','Hallandale Beach','Margate','Tamarac'],'Miami-Dade':['Miami','Miami Beach','Aventura','Coral Gables','Doral','Hialeah','Kendall','North Miami','Homestead','Miami Gardens','Miami Lakes','Sunny Isles Beach','Key Biscayne','South Miami','Pinecrest'],'Palm Beach':['Boca Raton','Delray Beach','West Palm Beach','Boynton Beach','Palm Beach','Jupiter','Wellington','Lake Worth Beach','Palm Beach Gardens','Lantana','Greenacres','Royal Palm Beach']};
function showCounty(county){document.querySelectorAll('[data-county]').forEach(x=>{const active=x.dataset.county===county;x.classList.toggle('active',active);x.setAttribute('aria-pressed',active)});$('#city-list').replaceChildren(...counties[county].slice(0,8).map(city=>{const b=document.createElement('button');b.textContent=city;b.addEventListener('click',()=>{$('#city-search').value=city;checkCity()});return b}))}
function checkCity(){const query=$('#city-search').value.trim().toLowerCase();if(!query){$('#city-result').textContent='Enter your city to check our South Florida service area.';return}const found=Object.entries(counties).find(([,cities])=>cities.some(c=>c.toLowerCase()===query));if(found){showCounty(found[0]);$('#city-result').textContent=`Yes — ${$('#city-search').value.trim()} is in our service area. Call or text to confirm mobile availability for your repair.`}else{$('#city-result').textContent='We may still cover your neighborhood. Call or text (954) 905-2386 to confirm — our service area includes many more communities.'}}
if($('#city-search')){document.querySelectorAll('[data-county]').forEach(b=>b.addEventListener('click',()=>showCounty(b.dataset.county)));$('#check-city').addEventListener('click',checkCity);$('#city-search').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();checkCity()}});showCounty('Broward')}
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',b===button)});let count=0;document.querySelectorAll('[data-category]').forEach(item=>{item.hidden=button.dataset.filter!=='all'&&item.dataset.category!==button.dataset.filter;if(!item.hidden)count++});$('#gallery-status').textContent=`Showing ${count} repair photo${count===1?'':'s'}.`;}));
const photoDialog=$('#photo-dialog');
if(photoDialog){document.querySelectorAll('[data-photo]').forEach(button=>button.addEventListener('click',()=>{const img=photoDialog.querySelector('img');img.src=button.dataset.photo;img.alt=button.dataset.caption;photoDialog.querySelector('p').textContent=button.dataset.caption;photoDialog.showModal();document.body.classList.add('modal-open')}));photoDialog.querySelector('.photo-close').addEventListener('click',()=>photoDialog.close());photoDialog.addEventListener('close',()=>document.body.classList.remove('modal-open'));photoDialog.addEventListener('click',e=>{if(e.target===photoDialog){const b=photoDialog.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)photoDialog.close()}})}
if(window.gsap&&!reduced){gsap.registerPlugin(ScrollTrigger);if($('.hero')){gsap.from('.hero-copy > *',{y:22,opacity:0,duration:.85,stagger:.09,ease:'power3.out',clearProps:'all'});gsap.from('.hero-visual',{opacity:0,duration:1.4,delay:.15});gsap.to('.background-word',{y:40,ease:'none',scrollTrigger:{trigger:'.hero',start:'top top',end:'bottom top',scrub:1}})}if($('.page-intro'))gsap.from('.page-intro > *',{y:18,opacity:0,duration:.65,stagger:.07,clearProps:'all'});gsap.utils.toArray('.section').forEach(section=>{const targets=section.querySelectorAll('.section-top, .service-card, .steps article, .work-heading, .work-photo, .location-card, .faq-items');if(targets.length)gsap.from(targets,{scrollTrigger:{trigger:section,start:'top 85%',once:true},opacity:0,y:24,stagger:.1,duration:.7,ease:'power2.out',clearProps:'all'})})}
